import type { Metadata } from "next";
import { SITE } from "@/config/site";

/**
 * Social card image generated by `src/app/opengraph-image.tsx`.
 * Resolved to an absolute URL through `metadataBase` in the root layout.
 */
export const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  type: "image/png",
} as const;

interface SocialOptions {
  title: string;
  description: string;
  /** Omit for non-routable pages (e.g. 404) so no dead `og:url` is emitted. */
  url?: string;
  type?: "website" | "article";
  publishedTime?: string;
  authors?: string[];
  section?: string;
}

/**
 * Open Graph + Twitter tags for a route. Next merges metadata shallowly, so a
 * page that defines `openGraph` must repeat the shared image — this helper keeps
 * every route consistent.
 */
export function social({
  title,
  description,
  url,
  type = "website",
  publishedTime,
  authors,
  section,
}: SocialOptions): Pick<Metadata, "openGraph" | "twitter"> {
  return {
    openGraph: {
      type,
      siteName: SITE.name,
      locale: "en_US",
      title,
      description,
      ...(url ? { url } : {}),
      images: [OG_IMAGE],
      ...(type === "article"
        ? {
            ...(publishedTime ? { publishedTime } : {}),
            ...(authors ? { authors } : {}),
            ...(section ? { section } : {}),
          }
        : {}),
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [OG_IMAGE],
    },
  };
}
